def parse_age(text):
    age = int(text)
    if age < 0: raise ValueError('Negative')
    return age
print(parse_age('10'))  # Output: 10

def eval_rpn(ops):
    stack = []
    for op in ops:
        if op in ('+', '-'):
            right = stack.pop()
            left = stack.pop()
            stack.append(left + right if op == '+' else left - right)
        else:
            stack.append(int(op))
    return stack[0]
print(eval_rpn(['4', '2', '-']))  # Output: 2

def fact(n):
    if n < 0:
        raise ValueError("Nonnegative input required")
    if n <= 1:
        return 1
    return n * fact(n-1)
print(fact(4))  # Output: 24

Tree maximum:
class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right
def tree_max(node):
    if not node: return float('-inf')
    return max(node.val, tree_max(node.left), tree_max(node.right))
print(tree_max(Node(1, Node(5), Node(3))))  # Output: 5

Path exists A to B:
from collections import deque
def path_exists(graph, start, target):
    q, visited = deque([start]), {start}
    while q:
        node = q.popleft()
        if node == target: return True
        for n in graph.get(node, []):
            if n not in visited: visited.add(n); q.append(n)
    return False
print(path_exists({'A':['B'], 'B':[]}, 'A', 'B'))  # Output: True

def withdraw(balance, amount):
    if type(balance) is not int or type(amount) is not int:
        raise ValueError('Use integer amounts')
    if balance < 0 or amount < 0 or amount > balance:
        raise ValueError('Invalid amount')
    return balance - amount
print(withdraw(100, 20))  # Output: 80

class DB:
    def __init__(self):
        self.data, self.pending = {}, {}
    def add(self, key, value):
        self.pending[key] = value
    def commit(self):
        self.data.update(self.pending)
        self.pending.clear()
    def rollback(self):
        self.pending.clear()
db = DB()
db.add('x', 1)
db.commit()
db.add('y', 2)
db.rollback()
print(db.data)  # Output: {'x': 1}
